/// 240 chars), else a placeholder.
String _skillDescription(SkillManifest manifest, String body) {
  var description = (manifest.catalogDescription ?? '').trim();
  if (description.isEmpty) {
    description = body
        .split('\n')
        .map((line) => line.trim())
        .firstWhere((line) => line.isNotEmpty, orElse: () => '');
