    this.whenToUse,
    this.argumentHint,
    this.arguments = const [],
    this.disableModelInvocation = false,
    this.userInvocable = true,
    this.allowedTools = const [],
    this.disallowedTools = const [],
    this.model,
    this.effort,
    this.contextFork = false,
    this.agent,
    this.background = true,
    this.paths = const [],
    this.shell,
    this.license,
    this.compatibility,
    this.metadata = const {},
    this.applyTo = const [],
    this.excludeAgent,
    this.notes = const [],
